INSERT INTO "Game" ("id","slug","title","description","tag","categories","tech","year","emoji","bgColor","published","sortOrder","portfolioSection","projectContext","role","contribution","contributions","team","recognition","features","highlights","platforms","inDevelopment","updatedAt")
VALUES (gen_random_uuid()::text, $q$water-sort-puzzle$q$, $q$Water Sort: Color Puzzle Game$q$, $q$A polished Water Sort puzzle game where players organize colored liquids into matching bottles through satisfying pour animations and progressively challenging levels. The project includes custom level tooling, animated gameplay feedback, haptics, themed visual assets, monetization systems, and Android mediation integration through the Hisavana package.$q$, $q$Casual & Puzzle$q$, ARRAY[$q$Unity$q$, $q$C#$q$, $q$Mobile Games$q$, $q$Puzzle Games$q$, $q$Android$q$, $q$Game Monetization$q$, $q$Level Design$q$, $q$Haptics$q$]::text[], $q$Unity, C#, Android Studio, Hisavana Mediation, DOTween, Unity Input System, Newtonsoft JSON$q$, $q$2025$q$, $q$🧪$q$, $q$#0284c7$q$, true, 1, $q$GAME$q$, $q$COMPANY$q$, $q$Unity Developer, Gameplay Programmer, and Monetization Integration Developer$q$, $q$Built and refined the core Water Sort gameplay loop, including bottle selection, liquid pouring, multi-liquid transfers, undo, hints, level completion, dynamic level layouts, and animated feedback. Developed editor tooling for JSON-based level creation and validation, while also integrating the Hisavana mediation package through Unity-facing managers and Android Studio build/dependency configuration.$q$, ARRAY[$q$Core Water Sort gameplay system$q$, $q$Liquid pouring and multi-liquid transfer animations$q$, $q$Bottle selection, sorting, completion detection, undo, and hint systems$q$, $q$Dynamic level loading from JSON files$q$, $q$Custom Water Sort level editor with validation and JSON export$q$, $q$Main menu, gameplay UI, loading flow, tutorial, pause, shop, and reward screens$q$, $q$Animated liquid rendering, black-overlay states, bottle caps, win effects, and confetti feedback$q$, $q$Audio, haptic feedback, button effects, and gameplay interaction polish$q$, $q$Hisavana mediation integration for banner, interstitial, and rewarded advertising$q$, $q$Android build and dependency configuration through Android Studio$q$]::text[], ARRAY[$q$Fishan Rajpoot$q$, $q$Muhammad Hassan Sajjad$q$, $q$Ahsan Tariq$q$, $q$Danish$q$, $q$BigTigGames$q$]::text[], $q$Delivered as a production-focused mobile puzzle game with a completed playable build, expanded level content, monetization integration, and Android mediation support.$q$, ARRAY[$q$Color-based Water Sort puzzle gameplay$q$, $q$Multiple liquid transfer and pour animations$q$, $q$Progressive level difficulty$q$, $q$Dynamic bottle layouts for different level sizes$q$, $q$Undo functionality$q$, $q$Hint system with best-move selection$q$, $q$Add-bottle gameplay support$q$, $q$Level completion detection and progression$q$, $q$JSON-driven level content$q$, $q$Custom in-Unity level editor$q$, $q$Level validation to ensure valid color-unit counts$q$, $q$Tutorial and onboarding flow$q$, $q$Themes and unlockable collection content$q$, $q$Shop and in-game reward systems$q$, $q$Banner, interstitial, and rewarded advertisements$q$, $q$Haptic feedback for gameplay interactions$q$, $q$Audio feedback for pouring, selection, success, and completion$q$, $q$Animated victory effects, confetti, particles, and UI transitions$q$]::text[], ARRAY[$q$Gameplay architecture: LevelManager, Holder, and Liquid coordinate level state, bottle contents, liquid transfers, sorting, undo, hints, and win detection.$q$, $q$Level authoring: LevelEditorWindow provides a Unity editor workflow for loading, editing, validating, renumbering, and saving JSON-based levels.$q$, $q$Animation system: DOTween drives bottle movement, liquid transitions, cap animations, completion feedback, UI transitions, and black-overlay fade effects.$q$, $q$Rendering: Liquid colors and fill amounts are updated dynamically through Liquid.cs, with support for bottle-bottom rendering and special black-sprite states.$q$, $q$Data flow: ResourceManager and GameManager load the current game mode and level data, then initialize gameplay through the Main scene.$q$, $q$Monetization integration: The Hisavana package contains Unity-facing managers for initialization, banners, interstitials, rewarded ads, and ad callbacks.$q$, $q$Android integration: Android Studio was used alongside Unity’s Android dependency tooling and project configuration to support the Hisavana mediation package and mobile advertising build pipeline.$q$, $q$Mobile feedback: Lofelt Nice Vibrations provides haptic responses for actions such as undo, hints, bottle additions, and other interactions.$q$, $q$Content pipeline: Level data is stored in JSON assets such as levels-easy.json, levels-challenges.json, and levels_merged.json.$q$, $q$Visual polish: Custom UI art, animated themes, particle effects, Cartoon FX effects, sound design, and animated victory feedback were integrated into the gameplay experience.$q$]::text[], $q$Android mobile, Unity Editor, Android Studio$q$, false, CURRENT_TIMESTAMP)
